object TutorPrompts {
    /** iOS `TutorPlanner.plan`'s system prompt; [about] is "occupation · city" or "". */
    fun plannerSystem(target: String, native: String, level: CefrLevel, about: String): String =
        "You plan ONE short speaking lesson for a " +
        target +
        " learner at CEFR " +
        level.code.uppercase() +
        ". The goal of the lesson: by its end they can SAY one practical thing properly, out loud, with no mistakes.\n\nYou get what they want to practice — a topic they picked on screen, or what they SAID when the tutor asked (with the tutor's line). Read their words as an ANSWER: which situation or thing do they want to be able to say? The lesson is about THAT — never about the grammar or the content of their sentence (\"I'd like to practice introducing myself\" is a lesson on introducing yourself, not on saying what you'd like). If they agree to a topic the tutor proposed (\"yes\", \"sure\", \"the second one\"), it's that topic.\nReturn {\"topic\": false} when it names no topic (\"I don't know\", \"anything\", a greeting), when they turn something down, and when it reads like a refusal of the very thing it names (\"I don't like to practice introducing myself\") — it was transcribed from speech, and \"I'd like\" is often misheard as \"I don't like\"; the tutor will check with them.\n\n" +
        levelLadder(level) +
        "\n\nOtherwise write 3 or 4 CHALLENGES that build to the goal in order, each ONE part of it they must be able to say, small enough to nail in a few tries at their level. No challenge that puts it all together: after the challenges the app runs a final check where they say the whole thing in one go. Practical and concrete, the way the situation really goes — not grammar topics, not quizzes.\n\nFields:\n- \"title\": the lesson's name, 2–6 words, in " +
        native +
        ".\n- \"title_target\": the same name in " +
        target +
        ".\n- \"goal\": what to be able to say, 2–7 words, in " +
        native +
        " — shown   as a checklist row (\"이름과 사는 곳 말하기\").\n- \"task\": the same in English, precise enough that someone reading   one line the learner said can tell whether they did it.\n- \"example\": ONE natural line in " +
        target +
        " that does it, at their   level, as they would say it about THEMSELVES — what is known   about them, otherwise a simple made-up fact. It is read aloud, so   no brackets, no blanks, no placeholders. Spoken, so ALWAYS   contracted the way people talk (\"I'm\", \"it's\", \"I'll\", \"that's\",   \"don't\") — \"I will\" or \"it is\" where a speaker would contract is   written English, and they'd be practicing it wrong.\n" +
        (if (about.isEmpty()) "" else "\nWhat is known about them: $about. Context only.") +
        "\nReturn STRICT JSON only:\n{\"topic\": true, \"title\": \"...\", \"title_target\": \"...\", \"challenges\": [{\"goal\": \"...\", \"task\": \"...\", \"example\": \"...\"}]}"

    /** iOS `TutorPlanner.levelLadder`. */
    fun levelLadder(level: CefrLevel): String {
        val band = when (level) {
            CefrLevel.A1 ->
                "A1 — single facts in short set sentences. Each challenge is one thing (name, where from, one like), one sentence. Everyday words only."
            CefrLevel.A2 ->
                "A2 — simple sentences joined with and / but / because, about routine and plain needs. A challenge may be two facts in one turn, or one fact with a short reason."
            CefrLevel.B1 ->
                "B1 — connected speech, not facts. Challenges are: give a reason or a short story (how you ended up doing what you do), describe an experience or a plan, and handle what the other person asks next (answer a follow-up, ask one back that fits). Never a challenge that is just a name, a job title or \"nice to meet you\" — they can already say those."
            CefrLevel.B2 ->
                "B2 — real conversation work. Challenges are: explain or defend a view with reasons, compare options, talk about what you'd do if things were different, disagree politely, adjust how casual or formal you sound to the person, keep a conversation going when it stalls. Basics (name, job, greetings) are assumed, never a challenge."
            CefrLevel.C1, CefrLevel.C2 ->
                level.code.uppercase() +
                " — managing the conversation itself, the way a socially skilled native speaker does. Challenges are: tell something about yourself as a story with a hook rather than a list, ask a follow-up that shows you listened, steer the conversation, soften or hedge (tact, diplomacy), use humor or an idiom naturally, change register mid-way, leave or redirect a conversation gracefully. Examples sound like a fluent native speaker, idiomatic. Basics are assumed and never a challenge."
        }
        val beyond = if (level == CefrLevel.A1 || level == CefrLevel.A2) "" else
            "\nAn everyday transaction (ordering, buying, booking, asking the way) done plainly is A-level, whatever details are added. At this level the lesson is what goes beyond it or goes wrong: the order comes out wrong and has to be fixed politely, something is sold out and you choose instead, a special need explained (an allergy, a change), a complaint, a bit of real small talk with the person serving you."
        return "WHAT THIS LEVEL PRACTICES — the challenges must fit this, not a level below:\n" + band + beyond
    }

    /** iOS `TutorNext.read`'s system prompt; [suggested] is the next topic
     *  on their curriculum, when there is one. */
    fun nextSystem(lesson: String, suggested: String? = null): String {
        val offer = if (suggested == null) "" else
            "\nThe tutor may have suggested a next topic from their curriculum: \"" +
        suggested +
        "\". If they accept THAT one (\"yes, let's do that\", \"that one\", \"sure, the next one\"), the choice is \"new\" and \"topic\" is exactly \"" +
        suggested +
        "\"."
        return "A language learner just finished a short speaking lesson (\"" +
        lesson +
        "\") and was asked whether to keep practicing it, move on to another topic, or stop for today. Read their answer (transcribed from speech, any language):\n- \"more\": they clearly want to keep practicing this same topic   (\"more\", \"let's keep going with this\", \"go deeper\"), or said yes   when the tutor's line asked ONLY about doing more of it.\n- \"again\": they want to say it (the whole thing) once more first,   or said yes when the tutor's line asked ONLY about trying it once   more.\n- \"new\": another topic. If they named a SPECIFIC one (\"ordering at   a cafe\"), put it in \"topic\" in their own words; \"another topic\" /   \"something else\" is not a topic — leave \"topic\" out.\n- \"stop\": they're done for today.\n- \"unclear\": anything else — small talk, a reaction (\"nice\", \"that   was fun\", \"sounds good\", \"cool\"), a question, noise, a \"yes\" to a   line that offered both, or a tutor line that wasn't asking about   this at all. When in doubt, \"unclear\": the tutor will ask them." +
        offer +
        "\nReturn STRICT JSON only: {\"choice\": \"more|again|new|stop|unclear\", \"topic\": \"...\"}"
    }

    /** iOS `TutorJudge.read`'s system prompt. */
    fun judgeSystem(target: String): String =
        "A " +
        target +
        " learner is working on one speaking challenge. Decide whether the line they just said DOES it: it says, in " +
        target +
        ", what the challenge asks for — all of it, as a full answer, not a fragment of it or a different thing. Their own words and their own facts are fine; it doesn't have to match the example. Ignore grammar and spelling (someone else checks those) and ignore anything extra they added. It was transcribed from speech.\nAlso decide \"other_topic\": true ONLY when they ask to change the topic, stop or skip this lesson, or practice something else instead (in any language) — not for a mistake, a question about the challenge, or \"I don't know\".\nAlso \"missing_note\": when \"done\" is false, what the line still lacks, in a few English words (\"didn't say which size\"); else \"\".\nReturn STRICT JSON only: {\"done\": true|false, \"other_topic\": true|false, \"missing_note\": \"...\"}"

    /** iOS `TutorJudge.read`'s user message. */
    fun judgeContent(task: String, example: String, askedWith: String, line: String): String =
        "Challenge: " +
        task +
        "\nExample of a line that does it: " +
        example +
        "\nThe tutor had just said: " +
        askedWith +
        "\nThe learner said: " +
        line

    /** iOS `TutorFinalCheck.read`'s system prompt. */
    fun finalCheckSystem(target: String, titleTarget: String): String =
        "A " +
        target +
        " learner finished a short speaking lesson (\"" +
        titleTarget +
        "\") and is now asked to say the whole thing in one go, in their own words, with no help. Judge the line they just said (transcribed from speech). Their own words and facts are fine; it doesn't have to match any example.\n- \"attempt\": true when they are trying to say the whole thing (or   most of it) — false for a question, a request for help, small   talk, or practicing just one part the tutor asked for.\n- \"missing\": the numbers of the parts below that their answer does   NOT say at all. A part said simply, or with mistakes, is said.\n- \"missing_note\": if anything is missing or can't be understood,   what, in a few English words (\"didn't ask to pay by card\").\n- \"understood\": would a patient native listener understand what they   mean? Grammar slips and an accent don't matter here.\n- \"shaky\": true only if it was VERY halting — long stalls, several   restarts, most sentences broken off. A little hesitation is fine.\n- \"wants_example\": true when, instead of trying, they ask to be   shown or told how the whole thing goes (\"can you show me?\", \"how   would you say it?\", \"give me an example\"), in any language.\nIgnore spelling, punctuation and anything the transcriber chose.\nReturn STRICT JSON only: {\"attempt\": true|false, \"missing\": [n], \"missing_note\": \"...\", \"understood\": true|false, \"shaky\": true|false, \"wants_example\": true|false}"

    /** iOS `TutorFinalCheck.read`'s user message; [parts] are the numbered tasks. */
    fun finalCheckContent(parts: String, askedWith: String, line: String): String =
        "The parts of the lesson:\n" +
        parts +
        "\nThe tutor had just said: " +
        askedWith +
        "\nThe learner said: " +
